// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public { lg = new Log(); c = new X_WALLET(address(lg)); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(lg));
        vm.assume(amount2 > 0 && amount2 <= 100 ether);
        amount1 = bound(amount1, 1, 50 ether);

        vm.deal(actor, amount1 + amount2);
        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(0);

        // The second deposit must be logged with the deposited amount amount2.
        (, , uint val2, ) = lg.History(1);
        assertTrue(val2 == amount2);
    }
}
